import itertools

# Given expression components
numbers = [2, 3, 4, 5]
operations = ['*', '+']

# Function to evaluate the expression with given parentheses
def evaluate_expression(expr):
    # This is a simple recursive function to evaluate the expression
    # We will use '1' to represent the addition operation for simplicity
    def eval_expr(expr):
        if len(expr) == 1:
            return expr[0]
        elif expr[0] == '*':
            return eval_expr(expr[1:]) * eval_expr(expr[2:])
        elif expr[0] == '+':
            return eval_expr(expr[1:]) + eval_expr(expr[2:])
        else:
            raise ValueError("Invalid operation")

    return eval_expr(expr)

# Generate all possible combinations of parentheses
def generate_parentheses(groupings):
    for grouping in groupings:
        expression = list(grouping)
        for i in range(1, len(expression)):
            if expression[i] == '*':
                expression[i] = '(' + expression[i] + ')'
            elif expression[i] == '+':
                expression[i] = '(' + expression[i] + ')'
        return expression

# Generate all possible groupings
all_groupings = []
for i in range(1, len(numbers) + 1):
    for combination in itertools.combinations(numbers, i):
        remaining = list(set(numbers) - set(combination))
        for j in range(1, len(remaining) + 1):
            for combination2 in itertools.combinations(remaining, j):
                groupings = [combination, remaining]
                groupings.append(combination2)
                all_groupings.append(groupings)

# Evaluate all unique groupings
unique_values = set()
for groupings in all_groupings:
    for expr in generate_parentheses(groupings):
        value = evaluate_expression(expr)
        unique_values.add(value)

# Count the number of unique values
unique_values_count = len(unique_values)
print(unique_values_count)
